using System.ComponentModel.Composition;
using XrmToolBox.Extensibility;
using XrmToolBox.Extensibility.Interfaces;

namespace SolutionAnalyzerFieldHealthChecker
{
    [Export(typeof(IXrmToolBoxPlugin)),
     ExportMetadata("Name", "Solution Analyzer & Field Health Checker"),
     ExportMetadata("Description", "Data-model quality reports: similar fields, duplicate option sets, field length usage, unused custom fields."),
     ExportMetadata("SmallImageBase64", SmallImage),   // Resources/logo32.png
     ExportMetadata("BigImageBase64", BigImage),       // Resources/logo80.png
     ExportMetadata("BackgroundColor", "Lavender"),
     ExportMetadata("PrimaryFontColor", "Black"),
     ExportMetadata("SecondaryFontColor", "Gray")]
    public class SolutionAnalyzerFieldHealthCheckerPlugin : PluginBase
    {
        // Tool logo shown in XrmToolBox's tool list (32x32 and 80x80 PNG, base64). Source images are in Resources/.
        const string SmallImage = "";
        const string BigImage = "";

        public override IXrmToolBoxPluginControl GetControl() => new MainControl();
    }
}
